package com.gathin.tvhome;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.lang.reflect.*;import java.io.*;
/** Software snapshots of the actual native view; only fixture apps, only a QA emulator. */
public class HomeVisualTest extends Instrumentation {
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 static void check(boolean value,String reason){if(!value)throw new AssertionError(reason);}
 static Field field(Class<?> type,String name)throws Exception{Field f=type.getDeclaredField(name);f.setAccessible(true);return f;}
 static ArrayList<Object> fixtures(android.content.res.Resources resources)throws Exception{ArrayList<Object> apps=new ArrayList<>();Class<?> type=Class.forName("com.gathin.tvhome.HomeSurface$App");Constructor<?> ctor=type.getDeclaredConstructor();ctor.setAccessible(true);String[] names={"YouTube","Prime Video","Netflix","Veyra","Music","Gallery","Cinema","TV"};int[] colors={0xffdf333b,0xff168bb7,0xff252832,0xff27786e,0xff8b509c,0xffba8245,0xff4a57a3,0xff3d7378};for(int i=0;i<names.length;i++){Object a=ctor.newInstance();field(type,"pkg").set(a,"fixture.app"+i);field(type,"name").set(a,names[i]);field(type,"component").set(a,new ComponentName("fixture.app"+i,"Main"));Bitmap b=Bitmap.createBitmap(360,200,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.drawColor(colors[i]);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setColor(Color.WHITE);paint.setTextSize(35);paint.setTextAlign(Paint.Align.CENTER);c.drawText(names[i],180,112,paint);field(type,"art").set(a,new BitmapDrawable(resources,b));field(type,"banner").set(a,true);apps.add(a);}return apps;}
 void snapshot(View view,String name)throws Exception{int width=view.getWidth(),height=view.getHeight();check(width>0&&height>0,"Unmeasured "+name);Bitmap b=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);view.draw(new Canvas(b));try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 @Override public void onStart(){Bundle result=new Bundle();try{
  MainActivity activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Throwable[] error={null};setInTouchMode(false);
  runOnMainSync(()->{try{HomeSurface.invalidateApps();field(HomeSurface.class,"cachedApps").set(null,fixtures(activity.getResources()));field(HomeSurface.class,"cachedCatalogRevision").setInt(null,field(HomeSurface.class,"catalogRevision").getInt(null));StudioConfig.prefs(activity).edit().putString("dock","fixture.app0,fixture.app1,fixture.app2,fixture.app3").apply();}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new AssertionError(error[0]);
  for(String id:StudioConfig.DESIGNS){
   runOnMainSync(()->{try{JSONObject config=StudioConfig.defaults().put("active",id).put("themes",new JSONArray().put(StudioConfig.preset(id)));StudioConfig.save(activity,config);activity.surface().refresh();}catch(Throwable e){error[0]=e;}});waitForIdleSync();Thread.sleep(350);sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_DOWN);waitForIdleSync();
   runOnMainSync(()->{try{HomeSurface home=activity.surface();home.goHome();home.measure(View.MeasureSpec.makeMeasureSpec(1920,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY));home.layout(0,0,1920,1080);snapshot(home,"Home-"+id);home.restoreSelection("fixture.app1",0);Map<?,?> focusTargets=(Map<?,?>)field(HomeSurface.class,"targets").get(home);View focusTarget=(View)focusTargets.get("fixture.app1");check(home.findFocus()!=home,"Cannot focus app in "+id+" touch="+home.isInTouchMode()+" window="+home.hasWindowFocus()+" shown="+(focusTarget!=null&&focusTarget.isShown())+" visibility="+(focusTarget==null?-1:focusTarget.getVisibility()));Map<?,?> targets=(Map<?,?>)field(HomeSurface.class,"targets").get(home);View power=(View)targets.get("power");Rect bounds=new Rect();check(power.getGlobalVisibleRect(bounds)&&bounds.bottom<=1080,"Power clipped in "+id);if(id.equals("classic")){Method customize=HomeSurface.class.getDeclaredMethod("customize");customize.setAccessible(true);customize.invoke(home);}}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new AssertionError(error[0]);waitForIdleSync();
   Thread.sleep(250);runOnMainSync(()->{try{snapshot(activity.surface(),"Home-"+id+"-focused");}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new AssertionError(error[0]);
   if(id.equals("cinema")){
    runOnMainSync(()->{try{HomeSurface home=activity.surface();home.restoreSelection("all",0);Map<?,?> targets=(Map<?,?>)field(HomeSurface.class,"targets").get(home);View toolbar=(View)targets.get("all");View parent=(View)toolbar.getParent();check(toolbar.getTop()>=0&&toolbar.getBottom()<=parent.getHeight(),"Toolbar focus extends outside its row");Rect bounds=new Rect();check(toolbar.getGlobalVisibleRect(bounds)&&bounds.width()==toolbar.getWidth()&&bounds.height()==toolbar.getHeight(),"Toolbar focus clipped");snapshot(home,"Home-cinema-toolbar");}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new AssertionError(error[0]);
   }
   if(id.equals("classic")){runOnMainSync(()->{try{PopupWindow popup=(PopupWindow)field(HomeSurface.class,"popup").get(activity.surface());snapshot(popup.getContentView(),"Home-customize");activity.surface().dismissMenu();}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new AssertionError(error[0]);}
  }
  runOnMainSync(()->{try{field(HomeSurface.class,"cachedApps").set(null,new ArrayList<>());for(String id:StudioConfig.DESIGNS){JSONObject theme=StudioConfig.preset(id).put("inputs","hide");for(String flag:StudioConfig.FLAGS)theme.put(flag,false);StudioConfig.save(activity,StudioConfig.defaults().put("active",id).put("themes",new JSONArray().put(theme)));activity.surface().refresh();check(((Map<?,?>)field(HomeSurface.class,"targets").get(activity.surface())).containsKey("customize"),"Empty design trapped user");}}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new AssertionError(error[0]);
  result.putString("stream","PASS: actual native Classic/Cinema/Panel software snapshots, app focus, unclipped Cinema toolbar bounds, visible Power, Customize popup, empty catalogs/all optional elements hidden retain Customize. Fixture apps only.\n");finish(0,result);
 }catch(Throwable e){StringWriter trace=new StringWriter();e.printStackTrace(new PrintWriter(trace));result.putString("stream",trace.toString());finish(1,result);}}
}
